CREATE TYPE "ReleaseStatus" AS ENUM ('DRAFT','READY_CHECK','READY','SCHEDULED','CANARY_PENDING','CANARY_RUNNING','CANARY_VALIDATING','CANARY_APPROVED','PROGRESSIVE_ROLLOUT','ROLLOUT_VALIDATING','FULL_RELEASE_PENDING','FULL_RELEASE','POST_RELEASE_MONITORING','VERIFIED','CERTIFIED','BLOCKED','REJECTED','PAUSED','ABORTED','ROLLED_BACK','ROLLBACK_FAILED','FAILED','EXPIRED','SUPERSEDED','INVALIDATED');
CREATE TYPE "ReleaseStrategy" AS ENUM ('CANARY','COHORT','PERCENTAGE','FEATURE_FLAG','REGION','CUSTOMER_SEGMENT','FULL_RELEASE');
CREATE TYPE "ReleaseStageStatus" AS ENUM ('PENDING','RUNNING','VALIDATING','PASSED','PAUSED','ABORTED','ROLLED_BACK','FAILED','SKIPPED');
CREATE TYPE "ReleaseGateResult" AS ENUM ('PASS','FAIL','BLOCKED','UNKNOWN');
CREATE TYPE "ReleaseDecisionType" AS ENUM ('READY','SCHEDULE','START','PROGRESS','PAUSE','RESUME','ABORT','ROLLBACK','VALIDATE','CERTIFY','INVALIDATE');
CREATE TYPE "ReleasePauseReason" AS ENUM ('HEALTH','INCIDENT','RECONCILIATION','SECURITY','PRIVACY','CAPACITY','COST','DEPENDENCY','FEATURE_FLAG_DRIFT','POLICY','MANUAL');
CREATE TYPE "ReleaseEvidenceType" AS ENUM ('READINESS','ARTIFACT','POLICY','DEPENDENCY','BASELINE','HEALTH','COHORT','PROGRESSION','PAUSE','ABORT','ROLLBACK','VALIDATION','CERTIFICATION','GRAPH','DIGITAL_TWIN','RECONCILIATION');
CREATE TYPE "ReleaseCertificationStatus" AS ENUM ('CERTIFIED','STALE','REVOKED','FAILED');
CREATE TYPE "ReleaseLockStatus" AS ENUM ('ACTIVE','RELEASED','EXPIRED');
CREATE TABLE "Release" ("id" UUID NOT NULL,"stableId" VARCHAR(200) NOT NULL,"changeRequestId" UUID NOT NULL,"changeRevision" INTEGER NOT NULL,"artifactId" UUID NOT NULL,"environment" VARCHAR(80) NOT NULL,"target" JSONB NOT NULL,"ownerId" VARCHAR(120) NOT NULL,"strategy" "ReleaseStrategy" NOT NULL,"status" "ReleaseStatus" NOT NULL DEFAULT 'DRAFT',"risk" VARCHAR(32) NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"validationStrategy" JSONB NOT NULL,"rollbackStrategy" JSONB NOT NULL,"releaseWindowId" UUID,"correlationId" VARCHAR(120) NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Release_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseArtifact" ("id" UUID NOT NULL,"stableId" VARCHAR(200) NOT NULL,"applicationVersion" VARCHAR(160) NOT NULL,"commitSha" VARCHAR(80),"buildIdentifier" VARCHAR(160) NOT NULL,"migrationVersion" VARCHAR(160),"configurationVersion" VARCHAR(160),"featureFlagVersion" VARCHAR(160),"dependencyLockHash" VARCHAR(128),"provenance" JSONB NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"approved" BOOLEAN NOT NULL DEFAULT false,"superseded" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseArtifact_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseStage" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"ordinal" INTEGER NOT NULL,"name" VARCHAR(80) NOT NULL,"exposure" JSONB NOT NULL,"minObservationSeconds" INTEGER NOT NULL,"maxExposure" INTEGER NOT NULL,"progressionPolicy" JSONB NOT NULL,"rollbackPolicy" JSONB NOT NULL,"status" "ReleaseStageStatus" NOT NULL DEFAULT 'PENDING',"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseStage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseStageExecution" ("id" UUID NOT NULL,"stageId" UUID NOT NULL,"idempotencyKey" VARCHAR(200) NOT NULL,"actorId" VARCHAR(120) NOT NULL,"result" "ReleaseStageStatus" NOT NULL,"evaluatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"healthSnapshot" JSONB NOT NULL,"decision" JSONB NOT NULL,"correlationId" VARCHAR(120) NOT NULL,CONSTRAINT "ReleaseStageExecution_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseGate" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"key" VARCHAR(100) NOT NULL,"category" VARCHAR(80) NOT NULL,"metric" VARCHAR(160) NOT NULL,"baseline" JSONB NOT NULL,"threshold" JSONB NOT NULL,"evaluationWindowSeconds" INTEGER NOT NULL,"minimumSampleSize" INTEGER NOT NULL,"failureTolerance" JSONB NOT NULL,"action" VARCHAR(32) NOT NULL,"required" BOOLEAN NOT NULL DEFAULT true,"result" "ReleaseGateResult" NOT NULL DEFAULT 'UNKNOWN',"observed" JSONB,"evaluatedAt" TIMESTAMP(3),CONSTRAINT "ReleaseGate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseDecision" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"decisionType" "ReleaseDecisionType" NOT NULL,"fromStatus" "ReleaseStatus" NOT NULL,"toStatus" "ReleaseStatus" NOT NULL,"actorId" VARCHAR(120) NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"reason" VARCHAR(1000) NOT NULL,"evidenceHash" VARCHAR(128) NOT NULL,"correlationId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseDecision_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleasePause" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"reason" "ReleasePauseReason" NOT NULL,"details" JSONB NOT NULL,"stageOrdinal" INTEGER NOT NULL,"healthSnapshot" JSONB NOT NULL,"actorId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"resumedAt" TIMESTAMP(3),CONSTRAINT "ReleasePause_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseRollback" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"stageOrdinal" INTEGER NOT NULL,"trigger" VARCHAR(120) NOT NULL,"policy" JSONB NOT NULL,"strategy" JSONB NOT NULL,"result" VARCHAR(40) NOT NULL,"remainingImpact" JSONB NOT NULL,"actorId" VARCHAR(120) NOT NULL,"validated" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseRollback_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseCertification" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"status" "ReleaseCertificationStatus" NOT NULL,"artifactHash" VARCHAR(128) NOT NULL,"policyVersion" VARCHAR(80) NOT NULL,"dependencySnapshot" JSONB NOT NULL,"healthEvidence" JSONB NOT NULL,"validationEvidence" JSONB NOT NULL,"validUntil" TIMESTAMP(3) NOT NULL,"certifiedBy" VARCHAR(120) NOT NULL,"certifiedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseCertification_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseEvidence" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"evidenceType" "ReleaseEvidenceType" NOT NULL,"source" VARCHAR(160) NOT NULL,"reference" VARCHAR(255) NOT NULL,"integrityHash" VARCHAR(128) NOT NULL,"payload" JSONB NOT NULL,"immutable" BOOLEAN NOT NULL DEFAULT true,"capturedBy" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseEvidence_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseInvalidation" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"reason" VARCHAR(500) NOT NULL,"changedDomain" VARCHAR(120) NOT NULL,"previousVersion" INTEGER NOT NULL,"actorId" VARCHAR(120) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseInvalidation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ReleaseLock" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"scope" VARCHAR(160) NOT NULL,"ownerId" VARCHAR(120) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"status" "ReleaseLockStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseLock_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Release_stableId_key" ON "Release"("stableId");CREATE INDEX "Release_changeRequestId_status_idx" ON "Release"("changeRequestId","status");CREATE INDEX "Release_environment_status_idx" ON "Release"("environment","status");CREATE UNIQUE INDEX "ReleaseArtifact_stableId_key" ON "ReleaseArtifact"("stableId");CREATE INDEX "ReleaseArtifact_approved_superseded_idx" ON "ReleaseArtifact"("approved","superseded");CREATE UNIQUE INDEX "ReleaseStage_releaseId_ordinal_key" ON "ReleaseStage"("releaseId","ordinal");CREATE UNIQUE INDEX "ReleaseStageExecution_idempotencyKey_key" ON "ReleaseStageExecution"("idempotencyKey");CREATE UNIQUE INDEX "ReleaseGate_releaseId_key_key" ON "ReleaseGate"("releaseId","key");CREATE INDEX "ReleaseDecision_releaseId_createdAt_idx" ON "ReleaseDecision"("releaseId","createdAt");CREATE UNIQUE INDEX "ReleaseLock_scope_status_key" ON "ReleaseLock"("scope","status");
ALTER TABLE "ReleaseStage" ADD CONSTRAINT "ReleaseStage_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseStageExecution" ADD CONSTRAINT "ReleaseStageExecution_stageId_fkey" FOREIGN KEY ("stageId") REFERENCES "ReleaseStage"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseGate" ADD CONSTRAINT "ReleaseGate_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseDecision" ADD CONSTRAINT "ReleaseDecision_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleasePause" ADD CONSTRAINT "ReleasePause_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseRollback" ADD CONSTRAINT "ReleaseRollback_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseCertification" ADD CONSTRAINT "ReleaseCertification_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseEvidence" ADD CONSTRAINT "ReleaseEvidence_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseInvalidation" ADD CONSTRAINT "ReleaseInvalidation_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReleaseLock" ADD CONSTRAINT "ReleaseLock_releaseId_fkey" FOREIGN KEY ("releaseId") REFERENCES "Release"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Release" ADD CONSTRAINT "Release_artifactId_fkey" FOREIGN KEY ("artifactId") REFERENCES "ReleaseArtifact"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "ReleaseWindow" ("id" UUID NOT NULL,"environment" VARCHAR(80) NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"kind" VARCHAR(40) NOT NULL,"frozen" BOOLEAN NOT NULL DEFAULT false,"reason" VARCHAR(500),"policyVersion" VARCHAR(80) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ReleaseWindow_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ReleaseWindow_environment_startsAt_endsAt_idx" ON "ReleaseWindow"("environment","startsAt","endsAt");
